INSERT INTO public.personas (id, nickname, gender, age, city, avatar, tagline, tags, manual, bio) VALUES
  ('a0000000-0000-4000-8000-000000000025', '许知夏', 'female', 29, '杭州', 'db:lorelei:许知夏', '产品经理，喜欢把日子过成一场小型展览', '["看展", "城市漫步", "独立电影", "咖啡馆"]'::jsonb, '{"mbti":"INFJ","element":"水象","zodiac":"巨蟹座","attachment":"安全型","loveLanguage":"精心的时刻","needs":"中需求","goal":"倾向长期","hobbies":["看展","城市漫步","独立电影","咖啡馆"],"values":["真诚","成长","边界感"],"oneLiner":"在杭州做产品，喜欢把普通周末过得有一点仪式感。","idealMatch":"愿意认真交流，也有自己的生活和热爱。"}'::jsonb, '在杭州做产品，工作节奏有忙有闲。周末喜欢看展、逛旧书店，偶尔一个人去陌生街区散步。'),
  ('a0000000-0000-4000-8000-000000000026', '周野', 'male', 32, '杭州', 'db:micah:周野', '建筑设计师，周末在山里找信号', '["徒步", "建筑", "胶片摄影", "露营"]'::jsonb, '{"mbti":"ISFP","element":"土象","zodiac":"金牛座","attachment":"安全型","loveLanguage":"服务的行动","needs":"低需求","goal":"倾向结婚","hobbies":["徒步","建筑","胶片摄影","露营"],"values":["稳定","自由","长期主义"],"oneLiner":"做建筑设计，喜欢安静工作，也喜欢在山里走很远。","idealMatch":"不急着定义关系，但愿意一起把日子过稳。"}'::jsonb, '做建筑设计，平时话不算多，但对在意的人很有行动力。假期会开车去山里露营，回城后再慢慢分享照片。'),
  ('a0000000-0000-4000-8000-000000000027', '林照', 'female', 25, '成都', 'db:adventurer:林照', '音乐剧演员，擅长把冷场变成即兴舞台', '["音乐剧", "livehouse", "烘焙", "猫"]'::jsonb, '{"mbti":"ENFP","element":"火象","zodiac":"双子座","attachment":"焦虑型","loveLanguage":"肯定的言语","needs":"高需求","goal":"倾向恋爱","hobbies":["音乐剧","livehouse","烘焙","猫"],"values":["热烈","表达","新鲜感"],"oneLiner":"喜欢舞台，也喜欢在厨房里研究失败率不低的甜点。","idealMatch":"会回应、愿意分享，也能在她兴奋时接住她的人。"}'::jsonb, '现在在成都生活和排练，喜欢边做甜点边听音乐，也会为了喜欢的乐队临时去另一座城市。'),
  ('a0000000-0000-4000-8000-000000000028', '沈砚', 'male', 27, '成都', 'db:micah:沈砚', '数据工程师，安静但有一整个奇怪的收藏柜', '["桌游", "科幻小说", "手冲咖啡", "博物馆"]'::jsonb, '{"mbti":"INTP","element":"风象","zodiac":"水瓶座","attachment":"疏离型","loveLanguage":"精心的时刻","needs":"低需求","goal":"不限","hobbies":["桌游","科幻小说","手冲咖啡","博物馆"],"values":["好奇","诚实","独立"],"oneLiner":"工作时喜欢解决复杂问题，生活里喜欢慢慢认识一件事。","idealMatch":"可以聊深，也不介意各自安静一会儿。"}'::jsonb, '做数据工程，生活规律但不无聊。喜欢桌游和科幻，遇到感兴趣的话题会从一个问题聊到凌晨。'),
  ('a0000000-0000-4000-8000-000000000029', '顾南枝', 'female', 34, '上海', 'db:lorelei:顾南枝', '出版社编辑，爱书也爱在菜市场挑一把花', '["文学", "古典音乐", "烹饪", "旅行"]'::jsonb, '{"mbti":"INTJ","element":"土象","zodiac":"处女座","attachment":"安全型","loveLanguage":"服务的行动","needs":"中需求","goal":"倾向结婚","hobbies":["文学","古典音乐","烹饪","旅行"],"values":["可靠","审美","家庭"],"oneLiner":"在上海做编辑，喜欢书页、音乐和把家里收拾得舒服。","idealMatch":"有稳定生活能力，也愿意一起讨论未来。"}'::jsonb, '做出版社编辑，平时喜欢读非虚构和逛菜市场。对关系的期待是可靠、坦诚，遇到问题愿意一起解决。'),
  ('a0000000-0000-4000-8000-000000000030', '闻川', 'male', 30, '上海', 'db:micah:闻川', '纪录片导演，习惯从小事里找故事', '["纪录片", "旅行", "潜水", "爵士乐"]'::jsonb, '{"mbti":"ENFJ","element":"水象","zodiac":"天蝎座","attachment":"安全型","loveLanguage":"高质量的陪伴","needs":"中需求","goal":"倾向长期","hobbies":["纪录片","旅行","潜水","爵士乐"],"values":["共情","行动","开放"],"oneLiner":"拍纪录片，也拍身边人的日常。相信好的关系需要共同经历。","idealMatch":"愿意进入彼此真实生活，而不只停留在聊天窗口。"}'::jsonb, '拍纪录片，项目忙起来会连轴转，空下来喜欢潜水或在小酒馆听爵士。看重真实，也愿意把时间花在重要的人身上。'),
  ('a0000000-0000-4000-8000-000000000031', '唐梨', 'female', 28, '南京', 'db:big-smile:唐梨', '心理咨询师，认真听你说完再给拥抱', '["心理学", "骑行", "植物", "手作"]'::jsonb, '{"mbti":"ISFJ","element":"水象","zodiac":"双鱼座","attachment":"安全型","loveLanguage":"身体接触","needs":"中需求","goal":"倾向长期","hobbies":["心理学","骑行","植物","手作"],"values":["温柔","信任","稳定"],"oneLiner":"喜欢照料植物，也喜欢把复杂情绪慢慢说清楚。","idealMatch":"情绪诚实、愿意沟通，不把沉默当惩罚。"}'::jsonb, '在南京工作，家里有一面植物墙。喜欢骑车去河边，关系里看重稳定回应和不带攻击性的沟通。'),
  ('a0000000-0000-4000-8000-000000000032', '程野', 'male', 26, '南京', 'db:adventurer:程野', '游戏策划，现实里也很会设计周末路线', '["游戏", "骑行", "脱口秀", "火锅"]'::jsonb, '{"mbti":"ENTP","element":"风象","zodiac":"白羊座","attachment":"疏离型","loveLanguage":"爱的行动","needs":"低需求","goal":"倾向恋爱","hobbies":["游戏","骑行","脱口秀","火锅"],"values":["有趣","自由","坦诚"],"oneLiner":"喜欢把无聊的事情改造成有意思的玩法。","idealMatch":"能一起开玩笑，也能尊重彼此的空间。"}'::jsonb, '做游戏策划，喜欢研究新玩法。周末会骑车、看脱口秀，偶尔给朋友做一桌不太正宗但很好吃的火锅。'),
  ('a0000000-0000-4000-8000-000000000033', '乔麦', 'female', 31, '北京', 'db:lorelei:乔麦', '纪录片制片人，清醒又保留一点浪漫', '["旅行", "摄影", "展览", "社会观察"]'::jsonb, '{"mbti":"ENTJ","element":"火象","zodiac":"摩羯座","attachment":"安全型","loveLanguage":"服务的行动","needs":"低需求","goal":"倾向结婚","hobbies":["旅行","摄影","展览","社会观察"],"values":["责任","独立","长期主义"],"oneLiner":"工作有目标，生活有审美，喜欢和人认真交换观点。","idealMatch":"有自己的方向，也愿意为共同生活留出时间。"}'::jsonb, '在北京做纪录片制片，工作常有短期出差。喜欢展览和城市观察，希望关系是两个完整的人互相照亮。'),
  ('a0000000-0000-4000-8000-000000000034', '陆沉', 'male', 35, '北京', 'db:micah:陆沉', '创业者，慢热，喜欢把承诺落在日历上', '["跑步", "咖啡", "历史", "家常菜"]'::jsonb, '{"mbti":"ISTJ","element":"土象","zodiac":"摩羯座","attachment":"安全型","loveLanguage":"服务的行动","needs":"中需求","goal":"倾向结婚","hobbies":["跑步","咖啡","历史","家常菜"],"values":["靠谱","家庭","持续"],"oneLiner":"工作上节奏快，关系里反而愿意慢慢来。","idealMatch":"不玩猜谜游戏，愿意把想法直接说出来。"}'::jsonb, '在北京创业，工作忙但作息相对稳定。喜欢晨跑、研究咖啡，也会认真学一道家常菜招待重要的人。')
